package io.wayfarer.rpg.core;

/** Original Greybridge scenes; progression and decisions live in the save, never in the UI. */
public final class StorySystem {
    private StorySystem(){}
    public static final String INTRO="1887年，灰桥。夜班列车迟到第三天，站务员诺拉·芬奇仍在给候车室添煤。\n\n她递来一张没有打孔的车票：‘我弟弟阿伦在那班车上。公司说没人登车，可这张票是他亲手交给我的。’\n\n你们沿货运线进入封锁区。列车不是消失了；有人把它从所有人的记录中删去了。每清理一处区域，都能在补给界面调查现场线索。";
    public static final String[] TITLES={"一 · 没有乘客的列车","二 · 岔道里的口令","三 · 仍在上工的人","四 · 提前写好的死亡","五 · 黑钟之下"};
    public static final String[] SCENES={
        "站场的车厢里没有尸体，只有叠得整齐的外套。最上面一件口袋里，怀表还在走。\n\n诺拉隔着铁栅喊出弟弟的名字。货运员留下的纸条却写着：‘先核人数，再注销姓名。’同一批工人同时出现在乘车簿与死亡名册上。\n\n一名清醒片刻的搬运工抓住你的衣袖：‘别让他们再叫点名。被叫到的人，会自己走回矿里。’他的手中有失踪者的住址，值班室里则留着公司的调度原件。",
        "林缘轨道分成两路。废弃岔道上没有新车辙，枕木下却传来列车刹车的声音。\n\n你找到信号员露丝。她将哨子埋进泥里：‘每晚有人用我的口令放行。我没吹过，可声音就是我的。’她的弟弟已跟着那声音走失。\n\n旧厂的工号牌挂在岔道尽头。露丝可以带幸存者绕过矿口，也可以陪你重新拼出当晚被篡改的行车时刻。",
        "旧纺织厂没有蒸汽，传动轴却仍在转。每一次织机落梭，墙后的某个人就忘掉自己的名字。\n\n阿伦还活着。他把一块写满姓名的布塞给你：‘忘掉之前，要有人替我们记住。’公司把工人的灵魂接在矿井的黑钟上，将他们当作不会下工的动力。\n\n拆掉传动装置能让受困者离开；抄下仪表与签字，则能证明这不是一次意外。你能先做哪一件？",
        "墓园账簿里的墨迹比墓碑新。牧守承认，空棺材在列车出发前就已入土，死亡证明也早已签好。\n\n诺拉终于见到阿伦。他叫得出姐姐的名字，却记不起自己的脸。‘他们说只借一个夜班。’他反复念着这句话。\n\n泵房监工塞缪尔曾试图停机，随后也被锁进了装置。账簿背页写着解约口令；另一页则记着仍被控制的人的位置。",
        "失魂监工倒下后，铁链还在替他抬起双手。塞缪尔清醒了一瞬：‘我签的是加班单，不是他们的命。’\n\n黑钟里回荡着整列车的点名声。它既保存契约，也保存每个人最后一点记忆。诺拉站在泵房门口，等你决定。\n\n立即切断契约，可以放走受困者，却会烧毁黑钟中的原始记录；封存核心，能留下完整证据，但残留的声音还需要漫长的安置。此前救下的人与留下的证词，会决定灰桥如何记住这一夜。"
    };
    public static final String[][] OPTIONS={{"先通知失踪者家属","带走调度原件"},{"护送露丝与幸存者","重建当晚行车记录"},{"先拆掉拘束装置","先保存试验签字"},{"按名单寻找活人","保全伪造死亡的证据"},{"切断契约，放走受困者","封存核心，公开契约"}};
    public static final String[][] PEOPLE={
        {"你没有一份能证明自己的职业文书。诺拉仍把车票交给你：‘肯回来的人，就值得托付。’", "旧厂里有人把你认成失踪的亲属。你知道自己不是那个人，却不忍立刻抽开被握住的手。", "回到站台，诺拉问该如何在名单上写你。你终于可以决定，是留下一个姓名，还是继续做路过的人。"},
        {"你曾答应把一名夜班工人送到家，却在封锁令下转身。那人的围巾如今挂在车厢里。", "阿伦认出了护路人的徽记。他没有责怪，只问：‘这次你会走在最后吗？’", "监工倒下后，出口先向你敞开。身后仍有人走不动，你又一次站在承诺与退路之间。"},
        {"林中的足迹太整齐，像有人在牵着一群人走。你认出一个旧猎伴磨偏的鞋跟。", "猎伴的声音从厂墙里叫你。他知道你小时候藏匕首的地方，也知道你不会轻易相信呼救。", "黑钟安静后，真正的猎伴没有回来。你必须决定，追踪的终点究竟是找到猎物，还是把寻找者带回家。"},
        {"你收藏过一张黑钟的拓片。如今它与车厢上的烙印完全相同，你却从未告诉同伴。", "厂内记录引用了你的旧文章。你以为只是学术争论的假说，已经被用来给活人编号。", "核心近在眼前，足以回答你一生的疑问。诺拉只问了一句：‘答案值得再留下一个人吗？’"},
        {"你认出了封锁令下的签名：旧上司曾教你，守住秩序比解释真相更重要。如今家属被挡在站门外。", "一份拘捕名单把所有失踪工人列为暴徒。阿伦问你，名字写在纸上，就能让一个人有罪吗？", "塞缪尔愿意作证，却曾替公司押送过工人。你手中有证据，也有立即宣判的力量。你将怎样结束这次调查？"},
        {"夜班口令来自你服役时的撤退暗号。你曾在那声口令后留下一个同伴，这次声音又响了。", "工人们把你当作能带他们冲出去的人。一个孩子却害怕你握枪时过于平静的表情。", "泵房里的声音模仿着阵亡同伴，下达‘一个不留’的命令。真正的同伴，过去总把最后一条退路留给别人。"},
        {"你给诺拉看过病，也曾在一张诊断书上写下‘不宜下井’。公司把那一行划掉，换成了‘适合夜班’。", "厂里的手术记录沿用了你的病例格式。阿伦还活着，而维持他清醒的装置正在耗尽另一个人的记忆。", "监工重伤倒地，幸存者等待离开。你知道怎样救他，也知道怎样从他身上取走自己需要的东西。医术的界线，现在由你守住。"},
        {"车站的一枚调速齿轮出自你的工坊。订单写着矿井排水，你从没见过验收人。", "旧厂把人的脉搏接进了调速装置。那些平稳的读数，曾是你最引以为傲的精度。", "黑钟的最后一处卡榫与你的旧图纸相同。拆掉它会毁掉你的作品，留下它则需要永远有人充当动力。"},
        {"你认得那条被封死的旧巷道。矿难那天，有人从里面敲了三下，第四下再没响起。", "阿伦说，地下的人仍在按班次换岗。他们相信，只要这一班结束，出口就会重新打开。", "泵房泄压时，你听见当年的第四下敲击。你可以再封一次井，也可以沿最危险的通道亲自去找人。"},
        {"诺拉的弟弟看过你的比赛，记得你曾扶起被击倒的对手。你却更记得那场输掉的奖金。", "一名被控制的工人摆出旧拳馆的架势。你能迅速击倒他，也能看见他每一次抬手都在违抗自己的意愿。", "监工已失去反抗的力气，你的双手仍在发抖。没人吹哨，也没人能替你决定什么时候停手。"},
        {"列车的煤款由你担保过。利润微薄，付款却快得反常，你当时没有追问。", "账册把工人的名字写进抵押品一栏。阿伦问你，一个人欠的钱，究竟能不能用一生来还？", "核心中的合同能洗清你的责任，也能让你得到最后一笔赔偿。幸存者只希望自己的名字从债务栏里消失。"},
        {"你曾把一宗矿难写成短讯，因为编辑说版面不够。诺拉保存着那张报纸，上面少了三个人的名字。", "厂里有人愿意给你完整内幕，条件是别把他的女儿写进报道。最有冲击力的标题，正需要她的名字。", "塞缪尔还没说完最后一句话，你已经想好了他的讣告。你得决定，自己是在记录一个人，还是替一个人安排结局。"}
    };
    public static final String[][] PERSONAL_OPTIONS={{"留下来照顾幸存者","亲自带路走完封锁线"},{"兑现护送的承诺","独自承担最后的阻击"},{"带寻找者平安回家","继续追踪失踪者的去向"},{"先保护眼前的人","公开自己的研究责任"},{"保护证人，补全证词","承担揭发上司的责任"},{"守住同伴的退路","亲自拒绝那道命令"},{"先保证伤者安全","追查试验源头并作证"},{"拆除拘束装置","公开自己的设计原件"},{"沿通道接回被困者","站在最危险的支撑点"},{"停手，保护倒下的人","承担护送队伍的前锋"},{"免去幸存者的债务","承认自己参与过担保"},{"隐去受害者的身份","署名公开完整调查"}};
    public static String personalTitle(int job,int chapter){return CareerSystem.CLASSES[job]+" · "+new String[]{"旧事","裂痕","回声"}[chapter];}
    public static String ending(int[] choices){
        for(int n:choices)if(n==0)return "还有未作决定的线索。";
        int rescue=0;for(int n:choices)if(n==1)rescue++;
        if(choices[4]==1&&rescue>=3)return "结局 · 归途有名：你带着幸存者回到车站。诺拉把一张张名字贴回候车室，灰桥终于有人走完了夜班。";
        if(choices[4]==2&&rescue<=2)return "结局 · 墨迹未干：契约与签字被公开，失踪不再能被称作意外。诺拉和你守着封存的黑钟，继续为残留的声音寻找归处。";
        return "结局 · 灯下余声：有人归来，有些证词永远缺了一页。你们把灯留在站台，答应每晚核对名单，直到再没有人被悄悄抹去。";
    }
}
